head.b:skin:
/*
-----------------------------------------------
Blogger Template: Media Downloader Landing
Developer: ANSNEW TECH — https://inside.ansnew.com
----------------------------------------------- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --white: #ffffff;
      --gray-50: #f8f9fb;
      --gray-100: #f1f3f5;
      --gray-200: #e2e5e9;
      --gray-300: #d0d4da;
      --gray-400: #9ca3af;
      --gray-500: #6b7280;
      --gray-600: #4b5563;
      --gray-700: #374151;
      --gray-800: #1f2937;
      --gray-900: #111827;
      --blue-50: #eff6ff;
      --blue-100: #dbeafe;
      --blue-500: #3b82f6;
      --blue-600: #2563eb;
      --blue-700: #1d4ed8;
      --emerald-50: #ecfdf5;
      --emerald-100: #d1fae5;
      --emerald-600: #059669;
      --amber-50: #fffbeb;
      --amber-100: #fef3c7;
      --amber-600: #d97706;
      --violet-50: #f5f3ff;
      --violet-100: #ede9fe;
      --violet-600: #7c3aed;
      --rose-50: #fff1f2;
      --rose-100: #ffe4e6;
      --rose-600: #e11d48;
      --radius: 12px;
      --ease: cubic-bezier(.4,0,.2,1);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      font-size: 15px;
      line-height: 1.6;
      color: var(--gray-700);
      background: var(--white);
      -webkit-font-smoothing: antialiased;
    }

    a { text-decoration: none; }
    a:not(.btn), a:not(.btn):hover, a:not(.btn):focus, a:not(.btn):active, a:not(.btn):visited { color: var(--blue-600); text-decoration: none; }
    a:not(.btn):hover { color: var(--blue-700); }
    img { max-width: 100%; height: auto; display: block; }
    code { font-family: 'SF Mono', monospace; font-size: .82em; background: var(--gray-100); padding: 2px 6px; border-radius: 5px; }
    kbd { font-family: inherit; font-size: .78em; font-weight: 500; background: var(--white); border: 1px solid var(--gray-200); border-bottom-width: 2px; border-radius: 5px; padding: 2px 7px; }

    .wrap { max-width: 1060px; margin: 0 auto; padding: 0 24px; }

    /* ── Navbar ── */
    .nav {
      position: sticky; top: 0; z-index: 50; height: 52px;
      background: rgba(255,255,255,.85);
      backdrop-filter: blur(14px) saturate(180%);
      -webkit-backdrop-filter: blur(14px) saturate(180%);
      border-bottom: 1px solid var(--gray-200);
    }
    .nav .wrap { display: flex; align-items: center; justify-content: space-between; height: 100%; }
    .logo { display: flex; align-items: center; gap: 9px; font-weight: 700; font-size: .93rem; color: var(--gray-900); }
    .logo img { width: 26px; height: 26px; border-radius: 6px; }
    .nav-list { display: flex; align-items: center; gap: 2px; list-style: none; }
    .nav-list a { display: block; padding: 5px 12px; font-size: .84rem; font-weight: 500; color: var(--gray-500); border-radius: 7px; transition: color .15s, background .15s; }
    .nav-list a:hover { color: var(--gray-900); background: var(--gray-50); }
    .nav-list a.btn { font-weight: 600; }
    .nav-list a.btn-fill,
    .nav-list a.btn-fill:hover { color: var(--white); background: var(--blue-600); border-color: var(--blue-600); }
    .nav-list a.btn-fill:hover { background: var(--blue-700); border-color: var(--blue-700); }
    .hamburger { display: none; background: none; border: none; cursor: pointer; color: var(--gray-700); }

    /* ── Buttons ── */
    .btn { display: inline-flex; align-items: center; gap: 7px; font-family: inherit; font-weight: 600; font-size: .84rem; padding: 9px 20px; border-radius: 9px; border: 1px solid transparent; cursor: pointer; transition: all .18s var(--ease); white-space: nowrap; }
    .btn svg { flex-shrink: 0; }
    .btn-fill { background: var(--gray-900); color: var(--white); border-color: var(--gray-900); }
    .btn-fill:hover { background: var(--gray-700); border-color: var(--gray-700); color: var(--white); }
    .btn-soft { background: var(--gray-100); color: var(--gray-700); border-color: var(--gray-200); }
    .btn-soft:hover { background: var(--gray-200); color: var(--gray-900); }
    .btn-ghost { background: none; color: var(--gray-500); padding-left: 8px; padding-right: 8px; }
    .btn-ghost:hover { color: var(--gray-900); }
    .btn-blue { background: var(--blue-600); color: var(--white); border-color: var(--blue-600); }
    .btn-blue:hover { background: var(--blue-700); border-color: var(--blue-700); color: var(--white); }
    .btn-sm { font-size: .8rem; padding: 7px 15px; }

    /* ── Hero ── */
    .hero { padding: 44px 0 40px; }
    .hero .wrap { display: grid; grid-template-columns: 1fr 1fr; gap: 36px; align-items: center; }
    .hero-label { display: inline-flex; align-items: center; gap: 7px; font-size: .74rem; font-weight: 600; text-transform: uppercase; letter-spacing: .05em; color: var(--emerald-600); background: var(--emerald-50); border: 1px solid var(--emerald-100); padding: 4px 12px; border-radius: 20px; margin-bottom: 14px; }
    .hero-label .dot { width: 5px; height: 5px; background: var(--emerald-600); border-radius: 50%; animation: pulse 2s ease-in-out infinite; }
    @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:.25} }
    .hero h1 { font-size: 2.3rem; font-weight: 800; line-height: 1.15; letter-spacing: -.025em; color: var(--gray-900); margin-bottom: 14px; }
    .hero h1 em { font-style: normal; color: var(--blue-600); }
    .hero-sub { color: var(--gray-500); font-size: 1rem; line-height: 1.65; margin-bottom: 8px; max-width: 460px; }
    .hero-sub strong { color: var(--gray-700); font-weight: 600; }
    .hero-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 18px; }
    .hero-byline { margin-top: 14px; font-size: .82rem; color: var(--gray-400); }
    .hero-byline a { color: var(--gray-500); font-weight: 600; transition: color .15s; }
    .hero-byline a:hover { color: var(--blue-600); }
    .hero-img { border-radius: 14px; border: 1px solid var(--gray-200); box-shadow: 0 4px 24px rgba(0,0,0,.06); transition: transform .4s var(--ease), box-shadow .4s var(--ease); }
    .hero-img:hover { transform: translateY(-4px); box-shadow: 0 10px 36px rgba(0,0,0,.09); }

    /* ── Sections ── */
    section { padding: 40px 0; }
    .sec-gray { background: var(--gray-50); }
    .sec-head { margin-bottom: 24px; }
    .sec-head h2 { font-size: 1.45rem; font-weight: 700; letter-spacing: -.015em; color: var(--gray-900); margin-bottom: 4px; }
    .sec-head p { color: var(--gray-500); font-size: .9rem; max-width: 520px; }
    .sec-head p a { color: var(--gray-600); font-weight: 600; transition: color .15s; }
    .sec-head p a:hover { color: var(--blue-600); }
    .centered { text-align: center; }
    .centered .sec-head p { margin: 0 auto; }

    /* ── What it does ── */
    .what-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
    }
    .what-card {
      text-align: center;
      padding: 22px 14px 18px;
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      background: var(--white);
      transition: box-shadow .2s var(--ease), border-color .2s var(--ease);
    }
    .what-card:hover { border-color: var(--gray-300); box-shadow: 0 3px 12px rgba(0,0,0,.04); }
    .what-icon {
      width: 48px; height: 48px;
      border-radius: 12px;
      display: flex; align-items: center; justify-content: center;
      margin: 0 auto 12px;
      font-size: 1.3rem;
    }
    .wi-blue   { background: var(--blue-50); }
    .wi-amber  { background: var(--amber-50); }
    .wi-violet { background: var(--violet-50); }
    .wi-green  { background: var(--emerald-50); }
    .what-card h3 { font-size: .88rem; font-weight: 600; color: var(--gray-800); margin-bottom: 4px; }
    .what-card p { font-size: .8rem; color: var(--gray-500); line-height: 1.55; }

    /* ── How it works ── */
    .steps {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
    }
    .step {
      position: relative;
      padding: 18px 16px;
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      background: var(--white);
    }
    .step-num {
      width: 26px; height: 26px;
      border-radius: 50%;
      background: var(--gray-900);
      color: var(--white);
      font-size: .72rem;
      font-weight: 700;
      display: flex; align-items: center; justify-content: center;
      margin-bottom: 10px;
    }
    .step h3 { font-size: .88rem; font-weight: 600; color: var(--gray-800); margin-bottom: 3px; }
    .step p { font-size: .82rem; color: var(--gray-500); line-height: 1.55; }

    /* ── Features detail ── */
    .feat-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
    .feat {
      padding: 18px;
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      background: var(--white);
      transition: box-shadow .2s var(--ease), border-color .2s var(--ease);
    }
    .feat:hover { border-color: var(--gray-300); box-shadow: 0 3px 12px rgba(0,0,0,.04); }
    .feat-top { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
    .feat-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
    .fd-blue   { background: var(--blue-600); }
    .fd-amber  { background: var(--amber-600); }
    .fd-violet { background: var(--violet-600); }
    .fd-green  { background: var(--emerald-600); }
    .feat-top h3 { font-size: .9rem; font-weight: 600; color: var(--gray-800); }
    .feat p { font-size: .84rem; color: var(--gray-500); line-height: 1.6; }
    .checklist { margin-top: 6px; }
    .check-item { font-size: .82rem; color: var(--gray-500); line-height: 1.6; padding-left: 18px; position: relative; margin-bottom: 2px; }
    .check-item::before { content: "\2713"; position: absolute; left: 0; color: var(--emerald-600); font-weight: 600; font-size: .75rem; }

    /* ── All tools strip ── */
    .tools-strip { display: grid; grid-template-columns: repeat(7, 1fr); gap: 8px; }
    .feat-grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
    .ts {
      text-align: center;
      padding: 14px 8px;
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      background: var(--white);
      transition: border-color .15s, box-shadow .15s;
    }
    .ts:hover { border-color: var(--gray-300); box-shadow: 0 2px 8px rgba(0,0,0,.03); }
    .ts-icon { font-size: 1.2rem; margin-bottom: 6px; display: block; }
    .ts h4 { font-size: .76rem; font-weight: 600; color: var(--gray-700); margin-bottom: 2px; }
    .ts p { font-size: .7rem; color: var(--gray-400); line-height: 1.4; }

    /* ── Shortcut table ── */
    .sc-box { border: 1px solid var(--gray-200); border-radius: var(--radius); overflow: hidden; background: var(--white); margin-top: 16px; }
    .sc-head { padding: 9px 16px; font-size: .7rem; font-weight: 600; text-transform: uppercase; letter-spacing: .06em; color: var(--gray-400); border-bottom: 1px solid var(--gray-200); }
    .sc-box table { width: 100%; border-collapse: collapse; }
    .sc-box td { padding: 6px 16px; font-size: .82rem; border-bottom: 1px solid var(--gray-100); color: var(--gray-600); }
    .sc-box tr:last-child td { border-bottom: none; }
    .sc-box td:first-child { width: 42%; color: var(--gray-400); }

    /* ── Download ── */
    .dl-row { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
    .dl-card {
      padding: 20px;
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      background: var(--white);
    }
    .dl-card h3 { font-size: .88rem; font-weight: 600; color: var(--gray-800); margin-bottom: 4px; }
    .dl-card p { font-size: .84rem; color: var(--gray-500); line-height: 1.6; }
    .dl-card .btn { margin-top: 12px; }
    .dl-btns { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
    .dl-btns .btn { margin-top: 0; }
    .dl-highlight {
      background: var(--blue-50);
      border-color: var(--blue-100);
    }

    /* ── Footer ── */
    .foot { border-top: 1px solid var(--gray-200); padding: 18px 0; }
    .foot .wrap { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; }
    .foot-brand { font-size: .84rem; font-weight: 600; color: var(--gray-800); margin-bottom: 2px; }
    .foot-brand a { color: var(--gray-600); font-weight: 600; transition: color .15s; }
    .foot-brand a:hover { color: var(--blue-600); }
    .foot-links { display: flex; flex-wrap: wrap; gap: 0; font-size: .78rem; }
    .foot-links a { color: var(--gray-400); text-decoration: none; transition: color .15s; }
    .foot-links a:hover { color: var(--gray-700); }
    .foot-links .dot { color: var(--gray-300); margin: 0 6px; }
    .foot-legal { font-size: .74rem; color: var(--gray-400); margin-top: 4px; }
    .foot .btn-fill,
    .foot .btn-fill:hover,
    .foot .btn-fill:focus,
    .foot .btn-fill:active,
    .foot .btn-fill:visited { color: var(--white); background: var(--blue-600); border-color: var(--blue-600); }
    .foot .btn-fill:hover { background: var(--blue-700); border-color: var(--blue-700); }

    /* ── Reveal ── */
    .rv { opacity: 0; transform: translateY(16px); transition: opacity .45s var(--ease), transform .45s var(--ease); }
    .rv.show { opacity: 1; transform: translateY(0); }

    /* ── Responsive ── */
    @media (max-width: 860px) {
      .hero .wrap { grid-template-columns: 1fr; gap: 24px; }
      .hero h1 { font-size: 1.9rem; }
      .what-grid { grid-template-columns: 1fr 1fr; }
      .steps { grid-template-columns: 1fr; }
      .feat-grid { grid-template-columns: 1fr; }
      .tools-strip { grid-template-columns: repeat(4, 1fr); }
      .feat-grid-3 { grid-template-columns: 1fr; }
      .dl-row { grid-template-columns: 1fr; }
    }
    @media (max-width: 580px) {
      .nav-list { display: none; }
      .nav-list.open { display: flex; flex-direction: column; position: absolute; top: 52px; left: 0; right: 0; background: var(--white); border-bottom: 1px solid var(--gray-200); padding: 8px 20px 12px; box-shadow: 0 6px 20px rgba(0,0,0,.06); }
      .hamburger { display: block; }
      .hero { padding: 28px 0 24px; }
      .hero h1 { font-size: 1.6rem; }
      section { padding: 28px 0; }
      .what-grid { grid-template-columns: 1fr; }
      .tools-strip { grid-template-columns: repeat(2, 1fr); }
      .hero-actions { flex-direction: column; }
      .hero-actions .btn { justify-content: center; }
    }

/* ── Blogger overrides ── */
#navbar, #navbar-iframe, .navbar, .blog-feeds, .post-feeds, .feed-links { display: none !important; height: 0; overflow: hidden; visibility: hidden; }
.sidebar { display: none !important; }

/* Hide blog widget output on the landing homepage */
body.homepage #main,
body.homepage .blog-posts,
body.homepage .post-outer,
body.homepage .post,
body.homepage .post-body,
body.homepage #Blog1,
body.homepage .main-inner { display: none !important; visibility: hidden !important; height: 0 !important; max-height: 0 !important; overflow: hidden !important; margin: 0 !important; padding: 0 !important; border: 0 !important; }

/* Always show landing content on Blogger (skip fade-in) */
#md-landing .rv { opacity: 1 !important; transform: none !important; }

/* Force landing cards/grid over Blogger defaults */
#md-landing .feat-grid { display: grid !important; grid-template-columns: 1fr 1fr !important; gap: 12px !important; }
#md-landing .feat { display: block !important; background: #ffffff !important; border: 1px solid #e2e5e9 !important; border-radius: 12px !important; padding: 18px !important; margin: 0 !important; }
#md-landing .checklist { display: block !important; margin: 6px 0 0 !important; padding: 0 !important; list-style: none !important; }
#md-landing .check-item { display: block !important; list-style: none !important; }

.not-home .blog-posts { max-width: 760px; margin: 0 auto; padding: 32px 24px; font-family: 'Inter', system-ui, sans-serif; }
.not-home .post { margin-bottom: 32px; padding-bottom: 24px; border-bottom: 1px solid #e2e5e9; }
.not-home .post-title a { color: #111827; font-size: 1.4rem; font-weight: 700; text-decoration: none; }
.not-home .post-body { color: #374151; line-height: 1.7; margin-top: 12px; }
.not-home .post-footer { font-size: .82rem; color: #9ca3af; margin-top: 12px; }
.not-home-back { display: inline-flex; margin: 16px 24px 0; }

@media (max-width: 860px) {
  #md-landing .feat-grid { grid-template-columns: 1fr !important; }
}

body.script:
  //
(function () {
  var toggle = document.getElementById('toggle');
  var menu = document.getElementById('menu');
  if (toggle && menu) {
    toggle.addEventListener('click', function () { menu.classList.toggle('open'); });
    menu.querySelectorAll('a').forEach(function (a) {
      a.addEventListener('click', function () { menu.classList.remove('open'); });
    });
  }
})();
  //
